<script setup>
import { onMounted, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import api, { errorMessage } from '../../composables/useAdminApi'
import AdminPageHeader from '../../components/AdminPageHeader.vue'
import AdminStatusBadge from '../../components/AdminStatusBadge.vue'
import AdminConfirmDialog from '../../components/AdminConfirmDialog.vue'

const props=defineProps({id:String}); const router=useRouter(); const project=ref(null); const loading=ref(true); const error=ref(''); const tab=ref('overview'); const confirm=ref(false); const busy=ref(false)
onMounted(async()=>{try{project.value=(await api.get(`/projects/${props.id}`)).data.data}catch(e){error.value=errorMessage(e)}finally{loading.value=false}})
async function archive(){busy.value=true;try{await api.post(`/projects/${props.id}/archive`);router.push({name:'projects.index'})}finally{busy.value=false}}
</script>

<template><div class="space-y-6"><AdminPageHeader :title="project?.name||'Project'" :eyebrow="project?.project_code||'Project detail'"><template v-if="project"><button class="admin-button admin-button--quiet" @click="confirm=true">Archive</button><RouterLink class="admin-button bg-dark text-light" :to="{name:'projects.edit',params:{id}}">Edit project</RouterLink></template></AdminPageHeader><p v-if="error" class="border border-red-700 bg-red-50 p-4 text-sm text-red-800">{{error}}</p><p v-if="loading" class="py-20 text-center">Loading...</p><template v-else-if="project"><nav class="flex gap-6 border-b border-dark font-mono text-xs font-bold uppercase"><button v-for="item in ['overview','contacts']" :key="item" class="border-b-4 px-1 pb-3 capitalize" :class="tab===item?'border-accent':'border-transparent'" @click="tab=item">{{item}}</button></nav><section v-if="tab==='overview'" class="grid gap-5 lg:grid-cols-2"><article class="border border-dark bg-light p-6"><div class="flex justify-between"><h2 class="font-mono font-bold uppercase">Project dossier</h2><AdminStatusBadge :status="project.status"/></div><dl class="mt-6 grid grid-cols-[120px_1fr] gap-y-3 text-sm"><dt class="text-neutral-500">Client</dt><dd><RouterLink :to="{name:'clients.show',params:{id:project.company.id}}" class="underline">{{project.company.name}}</RouterLink></dd><dt class="text-neutral-500">Product</dt><dd>{{project.service_product?.name||'—'}}</dd><dt class="text-neutral-500">Slug</dt><dd>{{project.url}}</dd><dt class="text-neutral-500">Started</dt><dd>{{project.started_at||'—'}}</dd><dt class="text-neutral-500">Completed</dt><dd>{{project.completed_at||'—'}}</dd></dl></article><article class="border border-dark bg-light p-6"><h2 class="font-mono font-bold uppercase">Context</h2><h3 class="mt-6 text-xs font-bold uppercase">Summary</h3><p class="mt-2 whitespace-pre-line text-sm">{{project.summary||'—'}}</p><h3 class="mt-5 text-xs font-bold uppercase">Internal notes</h3><p class="mt-2 whitespace-pre-line text-sm text-neutral-600">{{project.internal_notes||'—'}}</p></article></section><section v-if="tab==='contacts'" class="border border-dark bg-light"><article v-for="contact in project.contacts" :key="contact.id" class="grid gap-3 border-b border-neutral-300 p-4 last:border-0 sm:grid-cols-[1fr_auto]"><div><strong>{{contact.name}}</strong><p class="mt-1 text-sm text-neutral-600">{{contact.position||'Contact'}} · {{contact.email}}</p></div><div class="flex gap-2"><AdminStatusBadge :status="contact.active"/><span class="border border-neutral-400 px-2 py-1 font-mono text-[10px] font-bold uppercase">Portal: {{contact.can_access_portal?'yes':'no'}}</span></div></article><p v-if="!project.contacts.length" class="p-10 text-center text-sm text-neutral-600">No contacts assigned.</p></section></template><AdminConfirmDialog :open="confirm" title="Archive project?" text="The project will remain in historical records and can still be found with the archived filter." confirm-label="Archive project" :busy="busy" @close="confirm=false" @confirm="archive"/></div></template>